#!/usr/bin/env python3
"""
patch_line_wine.py
====================

Patches an existing Bottles (Flatpak) bottle so LINE for Windows
runs correctly under Wine:

  1. Installs a custom dwmapi.dll proxy that stops LINE's own
     drop-shadow "ghost window" bug from ever being visible, while
     keeping native window resize working. (Root cause: LINE creates
     8 auxiliary border/corner windows -- shadow_side_*/
     shadow_corner_* -- that Wine's DwmExtendFrameIntoClientArea
     can't provide (it's an empty stub in Wine); this proxy lets
     them draw normally but forces them fully transparent.)

  2. Fixes the LINE "NO_SIGNATURE" error (LINE 26.1.x+) by
     self-signing every DLL in the bottle's system32 and syswow64
     with a fake "Microsoft Corporation" certificate -- LINE's
     signature check only verifies a signature is PRESENT, not that
     it's valid, so this satisfies the check.
     (Source: https://forum.gamer.com.tw/Co.php?bsn=60030&sn=2550747)

Requirements on the HOST (not inside the bottle):
    - Bottles installed via Flatpak (com.usebottles.bottles)
    - openssl, osslsigncode  (script offers to install via apt if missing)
    - Python 3.8+

Usage:
    python3 patch_line_wine.py
"""

import base64
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

BOTTLES_DATA = Path.home() / ".var/app/com.usebottles.bottles/data/bottles"
BOTTLES_DIR = BOTTLES_DATA / "bottles"
RUNNERS_DIR = BOTTLES_DATA / "runners"

# The dwmapi.dll proxy, base64-encoded, embedded directly so this is a
# single self-contained file.
DWMAPI_DLL_B64 = """

""".strip()


def status(msg):
    print(f"==> {msg}")


def fail(msg):
    print(f"[!] {msg}", file=sys.stderr)
    sys.exit(1)


# --------------------------------------------------------------------
# Step 1: pick a bottle
# --------------------------------------------------------------------

def list_bottles():
    if not BOTTLES_DIR.is_dir():
        fail(f"Bottles data folder not found: {BOTTLES_DIR}\n"
             "    (is Bottles installed via Flatpak?)")
    bottles = sorted(p.name for p in BOTTLES_DIR.iterdir() if p.is_dir())
    if not bottles:
        fail(f"No bottles found under {BOTTLES_DIR}")
    return bottles


def choose_bottle():
    bottles = list_bottles()
    print("\nSelect the Bottle to work with:")
    for i, name in enumerate(bottles, 1):
        print(f"  {i}. {name}")
    while True:
        choice = input("Number: ").strip()
        if choice.isdigit() and 1 <= int(choice) <= len(bottles):
            return BOTTLES_DIR / bottles[int(choice) - 1]
        print("Invalid choice, try again.")


# --------------------------------------------------------------------
# Step 2: find the wine binary this bottle uses
# --------------------------------------------------------------------

def find_runner_name(bottle_path: Path):
    # Try the classic YAML config first.
    yml = bottle_path / "bottle.yml"
    if yml.is_file():
        text = yml.read_text(errors="ignore")
        m = re.search(r"^Runner:\s*(.+)$", text, re.MULTILINE)
        if m:
            return m.group(1).strip()

    # Try newer JSON-style configs.
    for name in ("configuration.json", "settings.json", "bottle.json"):
        f = bottle_path / name
        if f.is_file():
            try:
                data = json.loads(f.read_text(errors="ignore"))
            except (json.JSONDecodeError, OSError):
                continue
            runner = data.get("Runner") or data.get("runner")
            if runner:
                return runner

    return None


def find_wine_binary(bottle_path: Path):
    runner = find_runner_name(bottle_path)
    candidates = []
    if runner:
        candidates.append(RUNNERS_DIR / runner / "bin" / "wine64")
        candidates.append(RUNNERS_DIR / runner / "bin" / "wine")
    if not candidates or not any(c.is_file() for c in candidates):
        # Fall back: if only one runner is installed, use it.
        if RUNNERS_DIR.is_dir():
            available = sorted(p.name for p in RUNNERS_DIR.iterdir() if p.is_dir())
            if len(available) == 1:
                candidates.append(RUNNERS_DIR / available[0] / "bin" / "wine64")
                candidates.append(RUNNERS_DIR / available[0] / "bin" / "wine")
            elif available:
                print("\nCould not detect this bottle's runner automatically. "
                      "Choose the runner to use:")
                for i, name in enumerate(available, 1):
                    print(f"  {i}. {name}")
                choice = input("Number: ").strip()
                if choice.isdigit() and 1 <= int(choice) <= len(available):
                    name = available[int(choice) - 1]
                    candidates.append(RUNNERS_DIR / name / "bin" / "wine64")
                    candidates.append(RUNNERS_DIR / name / "bin" / "wine")

    for c in candidates:
        if c.is_file():
            return c
    fail("Could not find a wine binary for this bottle")


def run_wine(wine_bin: Path, bottle_path: Path, args):
    env = os.environ.copy()
    env["WINEPREFIX"] = str(bottle_path)
    env["WINEDEBUG"] = "-all"
    subprocess.run([str(wine_bin), *args], env=env, check=False,
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


# --------------------------------------------------------------------
# Step 3: install the dwmapi.dll proxy
# --------------------------------------------------------------------

def install_dwmapi_proxy(bottle_path: Path):
    system32 = bottle_path / "drive_c" / "windows" / "system32"
    dwmapi = system32 / "dwmapi.dll"
    dwmapi_real = system32 / "dwmapi_real.dll"

    if not dwmapi_real.is_file():
        if dwmapi.is_file():
            shutil.move(str(dwmapi), str(dwmapi_real))
        else:
            print("    [warn] No existing dwmapi.dll found in system32 (skipping backup)")

    dll_bytes = base64.b64decode(DWMAPI_DLL_B64)
    dwmapi.write_bytes(dll_bytes)


def set_dwmapi_native_override(wine_bin: Path, bottle_path: Path):
    # Wine's default DLL load order prefers its own builtin dwmapi.dll
    # over the file on disk -- without this override, the proxy above
    # is never actually loaded. Confirmed by direct testing: installing
    # the file alone had no effect until this override was set.
    #
    # "native,builtin" (not bare "native"): DllOverrides is a single
    # registry key shared identically by 32-bit and 64-bit processes
    # in a healthy prefix -- there's no way to scope it to system32
    # only via the registry. Our proxy is only ever placed in
    # system32 (64-bit), never in syswow64 (32-bit) -- see
    # install_dwmapi_proxy() above. With "native,builtin", a 64-bit
    # process finds our file there and uses it; a 32-bit process
    # finds no matching file in syswow64 and gracefully falls back to
    # Wine's builtin instead. A bare "native" (no fallback) would
    # instead make any 32-bit process needing dwmapi crash outright
    # with a missing-DLL error.
    run_wine(wine_bin, bottle_path, [
        "reg", "add", r"HKEY_CURRENT_USER\Software\Wine\DllOverrides",
        "/v", "dwmapi", "/d", "native,builtin", "/f",
    ])


# --------------------------------------------------------------------
# Step 4: NO_SIGNATURE fix -- self-sign every DLL in system32/syswow64
# --------------------------------------------------------------------

CODESIGN_CONF = """[req]
prompt = no
default_md = sha256
default_bits = 2048
distinguished_name = dn
x509_extensions = v3_req

[dn]
C = US
ST = Washington
L = Redmond
O = Microsoft Corporation
CN = Microsoft Windows

[v3_req]
subjectAltName = @alt_names

[alt_names]
DNS.1 = microsoft.com
"""


def ensure_tool_installed(binary_name, apt_package):
    if shutil.which(binary_name):
        return
    status(f"{binary_name} not found, installing via apt...")
    subprocess.run(["sudo", "apt", "install", "-y", apt_package], check=False)
    if not shutil.which(binary_name):
        fail(f"Failed to install {binary_name} -- install it manually and re-run this script")


def sign_all_dlls(bottle_path: Path):
    ensure_tool_installed("openssl", "openssl")
    ensure_tool_installed("osslsigncode", "osslsigncode")

    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        conf = tmp / "codesign.conf"
        key = tmp / "codesign.key"
        crt = tmp / "codesign.crt"
        conf.write_text(CODESIGN_CONF)

        subprocess.run([
            "openssl", "req", "-x509", "-new", "-nodes", "-sha256", "-utf8",
            "-days", "3650", "-newkey", "rsa:2048",
            "-keyout", str(key), "-out", str(crt), "-config", str(conf),
        ], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

        windows_dir = bottle_path / "drive_c" / "windows"
        dll_files = list((windows_dir / "system32").glob("*.dll")) + \
                    list((windows_dir / "syswow64").glob("*.dll"))

        for dll in dll_files:
            signed = dll.with_suffix(dll.suffix + ".signed")
            result = subprocess.run([
                "osslsigncode", "sign",
                "-certs", str(crt), "-key", str(key),
                "-in", str(dll), "-out", str(signed),
            ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if result.returncode == 0 and signed.is_file():
                signed.replace(dll)

        return len(dll_files)


# --------------------------------------------------------------------

def main():
    status("Reading list of bottles...")
    bottle_path = choose_bottle()
    status(f"Using bottle: {bottle_path.name}")

    status("Locating this bottle's wine binary...")
    wine_bin = find_wine_binary(bottle_path)

    status("Installing dwmapi.dll (fixes shadow/ghost window bug)...")
    install_dwmapi_proxy(bottle_path)

    status("Setting DllOverrides so Wine loads dwmapi.dll from disk...")
    set_dwmapi_native_override(wine_bin, bottle_path)

    status("Self-signing all DLLs (fixes NO_SIGNATURE)... this may take a moment")
    count = sign_all_dlls(bottle_path)
    status(f"Done signing {count} file(s)")

    status("Finished! You can now install LINE via its installer as usual.")


if __name__ == "__main__":
    main()
